    #[test]
    fn creation_content_is_validated() {
        let c = Content::load().unwrap();
        let mut two = c.clone();
        two.categories[1].skills.push(CategorySkill {
            id: SkillId::new("hacking"),
            cost: 100,
        });
        assert!(matches!(
            two.validate(),
            Err(ContentError::SkillInTwoCategories { .. })
        ));
        let mut none = c.clone();
        none.skills.push(Skill {
            id: SkillId::new("origami"),
            name: "Origami".into(),
            stat: Stat::Tech,
            desc: "paper".into(),
            needs: Vec::new(),
            after: Vec::new(),
        });
        assert!(matches!(
            none.validate(),
            Err(ContentError::SkillInNoCategory { .. })
        ));
        let mut costs = c.clone();
        costs.categories[0].skills[0].cost = 100;
        assert!(matches!(
            costs.validate(),
            Err(ContentError::FirstSkillCosts { .. })
        ));
        let mut step = c.clone();
        step.categories[0].skills[1].cost = 120;
        assert!(matches!(
            step.validate(),
            Err(ContentError::SpOffStep { cost: 120, .. })
        ));
        let mut step = c.clone();
        step.categories[0].cost = 75;
        assert!(matches!(
            step.validate(),
            Err(ContentError::SpOffStep { cost: 75, .. })
        ));
        let mut step = c.clone();
        step.creation.sp = 610;
        assert!(matches!(
            step.validate(),
            Err(ContentError::SpOffStep { cost: 610, .. })
        ));
        let mut kit = c.clone();
        kit.professions[0].kit.push((ItemId::new("ghost_item"), 1));
        assert!(matches!(
            kit.validate(),
            Err(ContentError::UnknownItem { .. })
        ));
        let mut t = c.clone();
        t.templates[0].origin = OriginId::new("nowhere");
        assert!(matches!(
            t.validate(),
            Err(ContentError::UnknownOrigin { .. })
        ));
        let mut e = c.clone();
        e.origins[0].emblem.pop();
        assert!(matches!(
            e.validate(),
            Err(ContentError::EmblemShape { .. })
        ));
    }

