    #[test]
    fn chrome_art_is_validated() {
        let c = Content::load().unwrap();
        let piston = ItemId::new("piston_arm");
        let invalid = |c: &Content| matches!(c.validate(), Err(ContentError::ChromeInvalid { .. }));
        let edited = |f: &dyn Fn(&mut ImplantArt)| {
            let mut e = c.clone();
            f(e.implant_art.get_mut(&piston).unwrap());
            e
        };
        let mut gone = c.clone();
        gone.implant_art.remove(&piston);
        assert!(invalid(&gone), "a piece without art");
        assert!(invalid(&edited(&|a| {
            a.rows[0].pop();
        })));
        assert!(invalid(&edited(&|a| {
            a.rows.pop();
        })));
        assert!(invalid(&edited(&|a| {
            a.colours.clear();
        })));
        assert!(invalid(&edited(&|a| {
            a.colours.insert('.', (1, 2, 3));
        })));
        let mut stray = c.clone();
        let art = stray.implant_art[&piston].clone();
        stray.implant_art.insert(ItemId::new("origami"), art);
        assert!(invalid(&stray), "art for an unknown item");
    }

    #[test]
    fn chrome_is_validated() {
        let c = Content::load().unwrap();
        let at = |c: &Content, id: &str| c.items.iter().position(|i| i.id.0 == id).unwrap();
        let broken = |id: &str, f: &dyn Fn(&mut Item)| {
            let mut bad = c.clone();
            let i = at(&bad, id);
            f(&mut bad.items[i]);
            bad.validate()
        };
        let invalid =
            |r: Result<(), ContentError>| matches!(r, Err(ContentError::ChromeInvalid { .. }));
        assert!(invalid(broken("neural_port", &|i| i.implant = None)));
        assert!(invalid(
            broken("neural_port", &|i| i.slot = Some(Slot::Head))
        ));
        assert!(invalid(broken("mirrorshades", &|i| {
            i.implant = Some(Implant {
                fits: Fits::Eyes,
                load: 1,
            })
        })));
        let load = |n: u8| move |i: &mut Item| i.implant.as_mut().unwrap().load = n;
        assert!(invalid(broken("neural_port", &load(0))));
        assert!(invalid(broken("neural_port", &load(6))));
        assert!(broken("neural_port", &load(5)).is_ok());
        assert!(invalid(broken("arc_hand", &|i| {
            i.sockets = vec![SocketKind::Hand]
        })));
        // Chrome sockets are a kind, not a site: an arm takes no gun sockets, a socket
        // piece fits only a chrome socket, and any piece may have chrome sockets.
        assert!(invalid(broken("grip_arm", &|i| {
            i.sockets = vec![SocketKind::Muzzle]
        })));
        assert!(invalid(broken("arc_hand", &|i| {
            i.implant.as_mut().unwrap().fits = Fits::Socket(SocketKind::Rail)
        })));
        let legs = broken("piston_arm", &|i| {
            i.implant.as_mut().unwrap().fits = Fits::Legs;
            i.sockets = vec![SocketKind::Hand];
        });
        assert!(legs.is_ok(), "{legs:?}");
        assert_eq!(
            ContentError::ChromeInvalid {
                id: "x".into(),
                why: "y".into()
            }
            .to_string(),
            "chrome `x`: y"
        );
    }

