    /// The rows of any art, to edit.
    fn rows_of(art: &mut SkillArt) -> &mut Vec<String> {
        match art {
            SkillArt::Hardware { rows, .. } | SkillArt::Neon { rows, .. } => rows,
        }
    }

    #[test]
    fn skill_art_and_needs_are_validated() {
        let c = Content::load().unwrap();
        let invalid = |c: &Content| matches!(c.validate(), Err(ContentError::SkillInvalid { .. }));
        // A copy with one skill's art edited.
        let edited = |id: &str, f: fn(&mut SkillArt)| {
            let mut e = c.clone();
            f(e.skill_art.get_mut(&SkillId::new(id)).unwrap());
            e
        };
        let mut gone = c.clone();
        gone.skill_art.remove(&SkillId::new("hacking"));
        assert!(invalid(&gone), "a skill without art");
        let short = edited("hacking", |a| {
            rows_of(a)[0].pop();
        });
        assert!(invalid(&short), "a row 33 wide");
        let few = edited("hacking", |a| {
            rows_of(a).pop();
        });
        assert!(invalid(&few), "19 rows");
        let uncoloured = edited("hacking", |a| {
            if let SkillArt::Hardware { colours, .. } = a {
                colours.remove(&'a');
            }
        });
        assert!(invalid(&uncoloured), "a pixel with no colour");
        let odd = edited("haggle", |a| rows_of(a)[0].replace_range(0..1, "x"));
        assert!(invalid(&odd), "a sign with a stray char");
        let dark = edited("haggle", |a| {
            for r in rows_of(a) {
                *r = ".".repeat(SKILL_ART_W);
            }
        });
        assert!(invalid(&dark), "a sign with no tube");
        let low = edited("hacking", |a| {
            if let SkillArt::Hardware { labels, .. } = a {
                labels.push((0, 10, "X".into(), (0, 0, 0), (0, 0, 0)));
            }
        });
        assert!(invalid(&low), "a label under the art");
        let far = edited("hacking", |a| {
            if let SkillArt::Hardware { labels, .. } = a {
                labels.push((u16::MAX, 0, "X".into(), (0, 0, 0), (0, 0, 0)));
            }
        });
        assert!(invalid(&far), "a label far off to the right");
        let dot = edited("hacking", |a| {
            if let SkillArt::Hardware { colours, .. } = a {
                colours.insert('.', (1, 2, 3));
            }
        });
        assert!(invalid(&dot), "a colour for the empty pixel");
        for n in [0, 11] {
            let mut need = c.clone();
            need.skills[0].needs = vec![(Stat::Net, n)];
            assert!(invalid(&need), "needs {n}");
        }
        let mut after = c.clone();
        after.skills[0].after = vec![SkillId::new("origami")];
        assert!(invalid(&after), "after an unknown skill");
        let mut stray = c.clone();
        let art = stray.skill_art[&SkillId::new("haggle")].clone();
        stray.skill_art.insert(SkillId::new("origami"), art);
        assert!(matches!(
            stray.validate(),
            Err(ContentError::UnknownSkill { .. })
        ));
    }
